        for c, v in enumerate(row):
            if v != bg:
                coords.setdefault(v, []).append((r, c))
    boxes = []
    for color, pts in coords.items():
        r0 = min(r for r,c in pts); r1 = max(r for r,c in pts)
        c0 = min(c for r,c in pts); c1 = max(c for r,c in pts)
        # A figure is a large rectangular region, possibly corrupted by noise.
